"use client";

import { FormEvent, useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { useSignupMutation, useLoginMutation } from "@/lib/services/authApi";
import { setAuthSession } from "@/lib/auth/client";
import { extractApiErrorMessage } from "@/lib/utils/extractApiErrorMessage";

interface AuthBoxProps {
  initialMode?: "signup" | "login";
}

export default function AuthBox({ initialMode = "login" }: AuthBoxProps) {
  const router = useRouter();
  // isSignupMode = true: Sign up form visible on the left, image on the right
  // isSignupMode = false: Sign in form visible on the right, image on the left
  const [isSignupMode, setIsSignupMode] = useState(initialMode === "signup");

  useEffect(() => {
    setIsSignupMode(initialMode === "signup");
  }, [initialMode]);

  const switchMode = (signup: boolean) => {
    setIsSignupMode(signup);
    setSignupStatus({ text: "", error: false });
    setLoginStatus({ text: "", error: false });
    if (typeof window !== "undefined") {
      window.history.pushState(null, "", signup ? "/signup" : "/login");
    }
  };

  const [signupMutation, { isLoading: isSigningUp }] = useSignupMutation();
  const [loginMutation, { isLoading: isLoggingIn }] = useLoginMutation();

  const [signupStatus, setSignupStatus] = useState<{ text: string; error: boolean }>({
    text: "",
    error: false,
  });

  const [loginStatus, setLoginStatus] = useState<{ text: string; error: boolean }>({
    text: "",
    error: false,
  });

  const handleSignupSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setSignupStatus({ text: "", error: false });

    const form = e.currentTarget;
    const formData = new FormData(form);

    const user = String(formData.get("user") || "").trim();
    const email = String(formData.get("email") || "").trim();
    const password = String(formData.get("password") || "");
    const confirmPassword = String(formData.get("confirmPassword") || "");

    if (password.length < 6) {
      setSignupStatus({ text: "Password must be at least 6 characters.", error: true });
      return;
    }

    if (password !== confirmPassword) {
      setSignupStatus({ text: "Passwords do not match.", error: true });
      return;
    }

    try {
      const response = await signupMutation({
        user,
        username: user.toLowerCase().replace(/[^a-z0-9._-]/g, ""),
        firstName: user,
        email,
        password,
        termsAccepted: true,
      }).unwrap();

      if (response?.token) {
        setAuthSession(response.token, response.user);
      }

      setSignupStatus({
        text: "Account created successfully! Redirecting...",
        error: false,
      });

      form.reset();
      setTimeout(() => {
        router.replace("/");
      }, 1000);
    } catch (error) {
      setSignupStatus({
        text: extractApiErrorMessage(error, "Signup failed. Please try again."),
        error: true,
      });
    }
  };

  const handleLoginSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoginStatus({ text: "", error: false });

    const form = e.currentTarget;
    const formData = new FormData(form);

    const user = String(formData.get("user") || "").trim();
    const password = String(formData.get("password") || "");

    try {
      const response = await loginMutation({
        user,
        email: user,
        password,
      }).unwrap();

      setAuthSession(response.token, response.user);
      setLoginStatus({ text: "Login successful! Redirecting...", error: false });

      setTimeout(() => {
        router.replace("/");
      }, 900);
    } catch (error) {
      setLoginStatus({
        text: extractApiErrorMessage(error, "Invalid user/email or password."),
        error: true,
      });
    }
  };

  return (
    <div className="theme-layout gray-bg vh-100">
      <div className="container">
        <div className="row justify-content-md-center">
          <div className="col-lg-8">
            <div className="logo-up">
              <Link href="/" className="logo">
                <img alt="Socimo" src="/images/socimo-logo.png" />
                <span>Socimo</span>
              </Link>
            </div>

            <div className={`box ${isSignupMode ? "is-signup" : ""}`}>
              <input
                type="checkbox"
                id="toggle"
                className="box__toggle"
                hidden
                checked={isSignupMode}
                readOnly
              />
              <img
                src="/images/resources/login-top.jpg"
                alt="Picture by Autumn Studio"
                className="box__image"
              />

              {/* Register Form (Left side) */}
              <form className="form form--register" onSubmit={handleSignupSubmit}>
                <span>
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="24"
                    height="24"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    className="feather feather-key"
                  >
                    <path d="M21 2l-2 2m-7.61 7.61a5.5 5.5 0 1 1-7.778 7.778 5.5 5.5 0 0 1 7.777-7.777zm0 0L15.5 7.5m0 0l3 3L22 7l-3-3m-3.5 3.5L19 4"></path>
                  </svg>
                </span>
                <h1 className="form__title">Sign up</h1>

                <div className="form__helper">
                  <input
                    type="text"
                    name="user"
                    id="new-user"
                    placeholder=" "
                    className="form__input"
                    required
                  />
                  <label className="form__label" htmlFor="new-user">
                    User
                  </label>
                </div>

                <div className="form__helper">
                  <input
                    type="email"
                    name="email"
                    id="email"
                    placeholder=" "
                    className="form__input"
                    required
                  />
                  <label className="form__label" htmlFor="email">
                    Email
                  </label>
                </div>

                <div className="form__helper">
                  <input
                    type="password"
                    name="password"
                    id="new-user-password"
                    placeholder=" "
                    className="form__input"
                    required
                    minLength={6}
                  />
                  <label className="form__label" htmlFor="new-user-password">
                    Password
                  </label>
                </div>

                <div className="form__helper">
                  <input
                    type="password"
                    name="confirmPassword"
                    id="confirm-password"
                    placeholder=" "
                    className="form__input"
                    required
                    minLength={6}
                  />
                  <label className="form__label" htmlFor="confirm-password">
                    Confirm password
                  </label>
                </div>

                <button type="submit" className="form__button" disabled={isSigningUp}>
                  {isSigningUp ? "Registering..." : "Register"}
                </button>

                {signupStatus.text && (
                  <p
                    className={`form__alert ${
                      signupStatus.error ? "form__alert--error" : "form__alert--success"
                    }`}
                  >
                    {signupStatus.text}
                  </p>
                )}

                <p className="form__text">
                  Already have an account?{" "}
                  <button
                    type="button"
                    className="form__link"
                    style={{
                      background: "transparent",
                      border: "none",
                      padding: 0,
                      font: "inherit",
                      cursor: "pointer",
                      display: "inline",
                    }}
                    onClick={() => switchMode(false)}
                  >
                    Sign in!
                  </button>
                </p>
              </form>

              {/* Login Form (Right side) */}
              <form className="form form--login" onSubmit={handleLoginSubmit}>
                <span>
                  <svg
                    id="login"
                    xmlns="http://www.w3.org/2000/svg"
                    width="24"
                    height="24"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    className="feather feather-users"
                  >
                    <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
                    <circle cx="9" cy="7" r="4" />
                    <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
                    <path d="M16 3.13a4 4 0 0 1 0 7.75" />
                  </svg>
                </span>
                <h1 className="form__title">Sign in</h1>

                <div className="form__helper">
                  <input
                    type="text"
                    name="user"
                    id="user"
                    placeholder=" "
                    className="form__input"
                    required
                  />
                  <label className="form__label" htmlFor="user">
                    User
                  </label>
                </div>

                <div className="form__helper">
                  <input
                    type="password"
                    name="password"
                    id="password"
                    placeholder=" "
                    className="form__input"
                    required
                  />
                  <label className="form__label" htmlFor="password">
                    Password
                  </label>
                </div>

                <button type="submit" className="form__button" disabled={isLoggingIn}>
                  {isLoggingIn ? "Logging in..." : "Login"}
                </button>

                {loginStatus.text && (
                  <p
                    className={`form__alert ${
                      loginStatus.error ? "form__alert--error" : "form__alert--success"
                    }`}
                  >
                    {loginStatus.text}
                  </p>
                )}

                <p className="form__text">
                  Don&apos;t have an account?{" "}
                  <button
                    type="button"
                    className="form__link"
                    style={{
                      background: "transparent",
                      border: "none",
                      padding: 0,
                      font: "inherit",
                      cursor: "pointer",
                      display: "inline",
                    }}
                    onClick={() => switchMode(true)}
                  >
                    Sign up!
                  </button>
                </p>
              </form>
            </div>
          </div>
        </div>
      </div>

      <figure className="bottom-mockup">
        <img alt="" src="/images/footer.png" />
      </figure>
      <div className="bottombar">
        <div className="container">
          <div className="row">
            <div className="col-lg-12">
              <span>&copy; Copyright All rights reserved by Socimo 2020</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
